import{_ as r,c as a,o as t,b0 as o}from"./chunks/framework.Dmsv_Tiv.js";const l="/media-docs/assets/image-20251128151455935.BmDc9uwp.png",n="/media-docs/assets/72d5c6cf1356b4f466be6aab719f6fab.BGuAA7Cg.jpg",i="/media-docs/assets/image-20251128154309343.D0puWwaY.png",p="/media-docs/assets/image-20251128161113750.B8Ky3Kz5.png",b=JSON.parse('{"title":"LV005-实时流传输协议简介","description":null,"frontmatter":{"title":"LV005-实时流传输协议简介","date":"2025-11-28T16:30:54.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/transmission/126b154ceaee35a22e51fb81","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-28T16:30:54.858Z","fulluuid":"22e51fb816914fcc834c510f97daf16e","useduuid":"22e51fb81"}},"headers":[],"relativePath":"sdoc/vcodec/transmission/126b154ceaee35a22e51fb81.md","filePath":"sdoc/20-视频编解码/10-视频传输/LV005-实时流传输协议简介.md","lastUpdated":1767537778000}'),s={name:"sdoc/vcodec/transmission/126b154ceaee35a22e51fb81.md"};function m(c,e,h,P,d,T){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="lv005-实时流传输协议简介" tabindex="-1">LV005-实时流传输协议简介 <a class="header-anchor" href="#lv005-实时流传输协议简介" aria-label="Permalink to &quot;LV005-实时流传输协议简介&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><h3 id="_1-流式传输" tabindex="-1">1. 流式传输 <a class="header-anchor" href="#_1-流式传输" aria-label="Permalink to &quot;1. 流式传输&quot;">​</a></h3><p>传统的网络传输音视频等多媒体信息的方式是完全下载后在播放，<strong>下载常常需要花数分钟甚至数小时</strong>。那我们平时见到的摄像头拍摄的画面，直接显示在大屏上，是实时显示的，肯定不是这种方式，那是用的什么方式？这就是接下来要了解的 <a href="https://baike.baidu.com/item/%E6%B5%81%E5%BC%8F%E4%BC%A0%E8%BE%93/4468472" target="_blank" rel="noreferrer">流式传输</a></p><p>看一下百度百科的定义：流式传输是一种通过网络连续传送 <a href="https://baike.baidu.com/item/%E6%B5%81%E5%AA%92%E4%BD%93/98740?fromModule=lemma_inlink" target="_blank" rel="noreferrer">流媒体</a> 数据的技术，用户无需下载完整文件即可实时播放音视频内容。该技术通过将媒体文件分解为数据包进行传输，播放器接收后即时解析播放，采用 <a href="https://baike.baidu.com/item/UDP/571511?fromModule=lemma_inlink" target="_blank" rel="noreferrer">UDP</a> 或 <a href="https://baike.baidu.com/item/TCP/33012?fromModule=lemma_inlink" target="_blank" rel="noreferrer">TCP</a> 协议满足不同场景需求。主要分为 <strong>实时流式传输</strong> 和 <strong>顺序流式传输</strong> 两种方式：实时流式传输依赖专用服务器及 <a href="https://baike.baidu.com/item/RTSP/1276768?fromModule=lemma_inlink" target="_blank" rel="noreferrer">RTSP</a> 等协议，支持随机访问并适配网络带宽，适用于直播场景；顺序流式传输基于 <a href="https://baike.baidu.com/item/HTTP/243074?fromModule=lemma_inlink" target="_blank" rel="noreferrer">HTTP</a>/<a href="https://baike.baidu.com/item/FTP/13839?fromModule=lemma_inlink" target="_blank" rel="noreferrer">FTP</a> 服务器，按顺序下载播放且无法跳转，播放前需等待部分内容缓存，但同时也支持在播放前将完整文件下载至本地，适合高质量短片播放。</p><h3 id="_2-流媒体" tabindex="-1">2. 流媒体 <a class="header-anchor" href="#_2-流媒体" aria-label="Permalink to &quot;2. 流媒体&quot;">​</a></h3><p>有时候会看到流媒体这样的概念，什么是流媒体？</p><p>先来看一下什么是媒体。媒体是个笼统的统称。我们能看到的，感知到的，能用来存放信息和传播信息的都可以叫做媒体。比如报纸、新闻、传媒（广播、电视、报刊杂志）、多媒体（计算机中的文字、声音、图像、视频等文件）都是”媒体“。甚至于磁带、磁盘、光盘和 U 盘、移动硬盘等也全都是”媒体“。</p><p><strong>流媒体</strong> 指的是通过”网络”传输的”媒体“，它还是媒体，只不过是在网络中“流动”的媒体，比如视频流、音频流、文字流等。比如我们日常用的较多的各种长短视频（奈飞、disney+、youtube、优酷，爱奇艺、某企鹅视频）、直播平台（斗鱼虎牙）和各种音乐平台（网抑云音乐、ku 狗，某企鹅扣扣音乐等）。</p><p>到这里，我们也知道了“流媒体”只是“媒体”里的其中一个子类，特指的经过网络传输的媒体。</p><p>那流媒体技术呢？流媒体想要在网络中传输当然也少不了“网络传输技术”，除了传输以外，当然少不了要传输的数据，也就是视频流、音频流等数据流。要处理这些数据则涉及到音视频制作、采集、制作、编解码、推流等“音视频处理技术”。”流媒体技术“，它其实就包含“<strong>网络传输技术</strong>”和“<strong>音视频处理技术</strong>”，两者缺一不可。</p><p>维基是上不去了，看下百度百科简单了解下吧：流媒体技术也称 <a href="https://baike.baidu.com/item/%E6%B5%81%E5%BC%8F%E5%AA%92%E4%BD%93%E6%8A%80%E6%9C%AF/2233323?fromModule=lemma_inlink" target="_blank" rel="noreferrer">流式媒体技术</a>.所谓流媒体技术就是把连续的影像和声音信息经过压缩处理 <a href="https://baike.baidu.com/item/%E5%90%8E%E6%94%BE/9911938?fromModule=lemma_inlink" target="_blank" rel="noreferrer">后放</a> 上 <a href="https://baike.baidu.com/item/%E7%BD%91%E7%AB%99%E6%9C%8D%E5%8A%A1%E5%99%A8/8156379?fromModule=lemma_inlink" target="_blank" rel="noreferrer">网站服务器</a>, 由 <a href="https://baike.baidu.com/item/%E8%A7%86%E9%A2%91%E6%9C%8D%E5%8A%A1%E5%99%A8/1607662?fromModule=lemma_inlink" target="_blank" rel="noreferrer">视频服务器</a> 向用户计算机顺序或实时地传送各个 <a href="https://baike.baidu.com/item/%E5%8E%8B%E7%BC%A9%E5%8C%85/5373066?fromModule=lemma_inlink" target="_blank" rel="noreferrer">压缩包</a>，让用户一边下载一边观看、收听，而不要等整个 <a href="https://baike.baidu.com/item/%E5%8E%8B%E7%BC%A9%E6%96%87%E4%BB%B6/7121310?fromModule=lemma_inlink" target="_blank" rel="noreferrer">压缩文件</a> 下载到自己的计算机上才可以观看的 <a href="https://baike.baidu.com/item/%E7%BD%91%E7%BB%9C%E4%BC%A0%E8%BE%93%E6%8A%80%E6%9C%AF/9591799?fromModule=lemma_inlink" target="_blank" rel="noreferrer">网络传输技术</a>。</p><p>所以呢，采用流媒体技术，可以实现流式传输，将声音、影像或动画由服务器想用户计算机进行连续、不间断传输，用户不必等到整个文件全部下载完毕，而只需要经过几秒或十几秒的启动延时即可进行观看。当声音视频等在用户的机器上播放时，文件的剩余部分还会从服务器上继续下载。</p><h2 id="二、流媒体协议" tabindex="-1">二、流媒体协议 <a class="header-anchor" href="#二、流媒体协议" aria-label="Permalink to &quot;二、流媒体协议&quot;">​</a></h2><p>关于流媒体传输协议，涉及到不同领域，不同业务场景，种类众多，下面一张图是现代的流媒体通信协议栈。</p><img src="'+l+'" alt="image-20251128151455935" style="zoom:67%;"><p>我们主要来看一下实时流协议数据传输依赖的这三种协议：RTSP、RTCP 和 RTP。RTP 和 RTSP 协议是应用层的，TCP 和 UDP 是传输层的，所以只能说 RTP over TCP/UDP ，而且一般情况下一个点播需要 RTSP+RTP+RTCP 三个协议共同来实现。几个概念的辨析：</p><ul><li><strong>RTP over UDP 和 RTP over RTSP 有什么区别</strong>？答：RTP over UDP 是 RTP 下层使用 UDP 传输，RTP over RTSP （这个现在一般都叫TCP）是指的用 RTSP 协议建立会话， 然后使用 RTP 协议传输数据。</li><li><strong>RTP over RTSP 是不是就是 RTP over TCP</strong>？答：不是。RTP over RTSP 是指的用 RTSP 协议建立会话，然后使用 RTP 协议传输数据，至于下面用 UDP 还是 TCP 是不确定的。</li></ul><h3 id="_1-rtsp-real-time-streaming-protocol-实时流式协议" tabindex="-1">1. RTSP (Real-Time Streaming Protocol) 实时流式协议 <a class="header-anchor" href="#_1-rtsp-real-time-streaming-protocol-实时流式协议" aria-label="Permalink to &quot;1. RTSP (Real-Time Streaming Protocol) 实时流式协议&quot;">​</a></h3><blockquote><p><a href="https://datatracker.ietf.org/doc/html/rfc2326" target="_blank" rel="noreferrer">RFC 2326 - Real Time Streaming Protocol (RTSP)</a></p></blockquote><p>RTSP(Real-Time Stream Protocol)是一种基于文本的应用层协议，是 RTP 的伴生协议，负责传输控制信息，而非媒体数据。由哥伦比亚大学, 网景和 RealNetworks 公司提交的 IETF RFC 标准。RTSP 以客户-服务器方式工作，它是一个应用层的多媒体播放控制协议。它和 HTTP 协议有些相似，其语法和操作参考了 HTTP/1.1，默认端口 554，而且可以在 TCP 和 UDP 上传输。</p><p>RTSP 本身并不传送数据，而仅仅是是媒体播放器能控制多媒体流的传送，暂停播放，快进快退等，必须依赖下层传输协议所提供的某些服务。实际媒体数据的传输可以用 RTP 协议或其他专用协议。</p><blockquote><p>RTSP 主要应用在视频监控领域，网络摄像头都支持 RTSP 协议。</p></blockquote><h3 id="_2-rtcp-rtp-control-protocol-实时运输控制协议" tabindex="-1">2. RTCP (RTP Control Protocol)实时运输控制协议 <a class="header-anchor" href="#_2-rtcp-rtp-control-protocol-实时运输控制协议" aria-label="Permalink to &quot;2. RTCP (RTP Control Protocol)实时运输控制协议&quot;">​</a></h3><blockquote><p><a href="https://datatracker.ietf.org/doc/html/rfc3550" target="_blank" rel="noreferrer">RFC 3550 - RTP: A Transport Protocol for Real-Time Applications</a></p><p><a href="https://datatracker.ietf.org/doc/html/rfc3551" target="_blank" rel="noreferrer">RFC 3551 - RTP Profile for Audio and Video Conferences with Minimal Control</a></p></blockquote><p>实时传输控制协议(<strong>R</strong> eal-<strong>t</strong> ime <strong>C</strong> ontrol <strong>P</strong> rotocol，RTCP)是 <a href="https://baike.baidu.com/item/%E5%AE%9E%E6%97%B6%E4%BC%A0%E8%BE%93%E5%8D%8F%E8%AE%AE/9365206?fromModule=lemma_inlink" target="_blank" rel="noreferrer">实时传输协议</a>（RTP）的配套控制协议，由 <a href="https://baike.baidu.com/item/IETF/2800318?fromModule=lemma_inlink" target="_blank" rel="noreferrer">IETF</a> 在 RFC 3550 中定义，基于 <a href="https://baike.baidu.com/item/UDP%E5%8D%8F%E8%AE%AE/421768?fromModule=lemma_inlink" target="_blank" rel="noreferrer">UDP 协议</a> 通过相邻端口实现控制流与数据流分离传输。它本身也是不传输数据的，主要功能是为 RTP 提供服务质量反馈。包含媒体链接的统计信息，例如传输字节数，丢失的分组数，单向和双向网络延迟等。</p><p>RTCP 的主要功能：服务质量的监督和反馈，媒体数据间的同步，以及多播组中成员的标志。RTCP 分组很短，通常多个分组封装在一个 UDP 数据报中。</p><h3 id="_3-rtp-real-time-transport-protocol-实时运输协议" tabindex="-1">3. RTP (Real-Time Transport Protocol) 实时运输协议 <a class="header-anchor" href="#_3-rtp-real-time-transport-protocol-实时运输协议" aria-label="Permalink to &quot;3. RTP (Real-Time Transport Protocol) 实时运输协议&quot;">​</a></h3><blockquote><p><a href="https://datatracker.ietf.org/doc/html/rfc3550" target="_blank" rel="noreferrer">RFC 3550 - RTP: A Transport Protocol for Real-Time Applications</a></p><p><a href="https://datatracker.ietf.org/doc/html/rfc3551" target="_blank" rel="noreferrer">RFC 3551 - RTP Profile for Audio and Video Conferences with Minimal Control</a></p></blockquote><p>RTP 是一种基于 UDP 的传输协议，专为实时数据传输设计，由 IETF 在 RFC 3550 中定义。其核心功能是提供时间戳、序列号和负载类型标识，确保音视频数据的时序同步和丢包检测，主要负责对媒体数据进行封包并实现媒体流的实时传输。RTP 本身不保证服务质量（QoS），但通过 RTCP 实现监控和反馈。</p><h3 id="_4-小结" tabindex="-1">4. 小结 <a class="header-anchor" href="#_4-小结" aria-label="Permalink to &quot;4. 小结&quot;">​</a></h3><ul><li>RTP、RTSP 和 RTCP 是什么关系？</li></ul><p><strong>RTSP</strong>：建立和控制会话，负责服务器与客户端之间的请求与响应。</p><p><strong>RTP</strong>：传输实际的音视频数据。</p><p><strong>RTCP</strong>：监控网络状况，优化 RTP 传输。</p><img src="'+n+'" alt="img" style="zoom:67%;"><p>rtsp承载与rtp和rtcp之上，rtsp并不会发送媒体数据，而是使用rtp协议传输。rtp并没有规定发送方式，可以选择udp发送或者tcp发送。</p><h2 id="三、实时流传输协议交互" tabindex="-1">三、实时流传输协议交互 <a class="header-anchor" href="#三、实时流传输协议交互" aria-label="Permalink to &quot;三、实时流传输协议交互&quot;">​</a></h2><h3 id="_1-rtsp-流媒体服务器" tabindex="-1">1. RTSP 流媒体服务器 <a class="header-anchor" href="#_1-rtsp-流媒体服务器" aria-label="Permalink to &quot;1. RTSP 流媒体服务器&quot;">​</a></h3><p>下图是一个基于 RTSP 的流媒体服务器的实现：</p><img src="'+i+'" alt="image-20251128154309343"><p>客户端通过 RTSP 协议与媒体服务器建立会话，获取媒体能力集、参数等。当客户端发起 play 请求后，会建立两个端口的连接，分别供 RTP 和 RTCP 使用。客户端通过 RTCP 周期性反馈媒体链接的统计信息，例如传输字节、丢包、网络延迟信息等。网络应用程序利用 RTCP 的统计信息控制传输的质量，例如限流或者更新编码参数等。服务端通过 RTP 协议将媒体数据封装发送，包含音频、视频和一些私有数据。</p><h3 id="_2-交互过程中的协议" tabindex="-1">2. 交互过程中的协议 <a class="header-anchor" href="#_2-交互过程中的协议" aria-label="Permalink to &quot;2. 交互过程中的协议&quot;">​</a></h3><p>下图是 RTP 数据流交互的应用层、传输层和网络层协议关系：</p><p><img src="'+p+'" alt="image-20251128161113750"></p><p>其中 RTSP 通常是基于 TCP 协议，RTP 和 RTCP 是基于 UDP 协议分组发送。需要注意的是，由于 RTP 数据协议不包含负载数据的长度，所以规定使用 UDP 传输时，单包数据是一个 RTP 包。</p><blockquote><p>参考资料：</p><p><a href="https://zhuanlan.zhihu.com/p/550261286" target="_blank" rel="noreferrer">(5 封私信) 什么是流式传输？ - 知乎</a></p><p><a href="https://zhuanlan.zhihu.com/p/384625487" target="_blank" rel="noreferrer">(5 封私信) 这可能是全网最全的流媒体知识科普文章 - 知乎</a></p><p><a href="https://www.cnblogs.com/kn-zheng/p/17381837.html" target="_blank" rel="noreferrer">流媒体协议技术等大总结 - 阿风小子 - 博客园</a></p><p><a href="https://zhuanlan.zhihu.com/p/496823042" target="_blank" rel="noreferrer">(5 封私信) 流媒体协议 RTP、RTSP、RTMP、HLS、SRT、WebRTC 全面分析 - 知乎</a></p><p><a href="https://zhuanlan.zhihu.com/p/683643576" target="_blank" rel="noreferrer">(5 封私信) 深入解析 RTSP 协议：流媒体传输的控制核心 - 知乎</a></p><p><a href="https://www.cnblogs.com/iFrank/p/15434438.html" target="_blank" rel="noreferrer">【rtp over tcp/rtsp解析】&amp;&amp;【H264格式与RTP包解析】&amp;&amp;【以H264的打包方式---分片打包(type = 28 FU-A方式为例)】 - `Konoha - 博客园</a></p></blockquote>',47)])])}const u=r(s,[["render",m]]);export{b as __pageData,u as default};
